<script setup lang="ts">
/**
 * FileUpload.Row: one file, with its status and its controls, playing its exit when it leaves.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/file-upload.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { useTemplateRef, watch } from 'vue'

import { Icon } from '@polymorph/vue'
import { usePresence } from '@polymorph/vue/motion'
import styles from '@polymorph/recipes/controls/file-upload.module.css'
import Button from './Button.vue'
import Progress from '../structure/Progress.vue'
import type { FileUploadItem } from './FileUpload.vue'

export interface FileUploadRowProps {
  file: FileUploadItem
  /**
   * False once the file has left the list, while the row plays its exit.
   */
  open: boolean
  /**
   * The size, formatted by the messages.
   */
  size?: string
  /**
   * The app handles a retry, so a failed row offers one.
   */
  retryable: boolean
  /**
   * The field is disabled, and the row’s controls with it.
   */
  disabled: boolean
  retryLabel: string
  removeLabel: string
  progressLabel: string
}

defineOptions({ name: 'FileUploadRow', inheritAttrs: false })

const props = defineProps<FileUploadRowProps>()
const emit = defineEmits<{ retry: []; remove: []; done: [] }>()
const row = useTemplateRef<HTMLElement>('row')
const present = usePresence(() => props.open, row, 'fileupload.row')
const effect1 = () => {
  present.value || emit('done')
}
watch(() => present.value, effect1, { flush: 'post' })
</script>

<template>
  <li ref="row" :class="styles.row" :data-status="file.status">
    <!-- rowIcon -->
    <span :class="styles.rowIcon">
      <Icon name="document" />
    </span>
    <!-- details -->
    <span :class="styles.details">
      <!-- name -->
      <span :class="styles.name">
        {{ file.name }}
      </span>
      <!-- meta -->
      <span v-if="size !== undefined" :class="styles.meta">
        {{ size }}
      </span>
      <!-- message -->
      <span v-if="file.status === 'error' && file.message !== undefined" :class="styles.message">
        {{ file.message }}
      </span>
    </span>
    <!-- trailing -->
    <span v-if="file.status === 'uploading'" :class="styles.trailing">
      <!-- progress -->
      <span :class="styles.progress">
        <Progress :value="file.progress ?? 0" :label="progressLabel" />
      </span>
      <!-- percent -->
      <span :class="styles.percent">
        {{ `${Math.round(file.progress ?? 0)}%` }}
      </span>
    </span>
    <!-- done -->
    <span v-if="file.status === 'done'" :class="styles.done">
      <Icon name="success" />
    </span>
    <Button
      v-if="file.status === 'error' && retryable"
      variant="ghost"
      tone="neutral"
      size="sm"
      :iconOnly="true"
      icon="refresh"
      :label="retryLabel"
      :disabled="disabled"
      @click="emit('retry')"
    />
    <Button
      variant="ghost"
      tone="neutral"
      size="sm"
      :iconOnly="true"
      icon="close"
      :label="removeLabel"
      :disabled="disabled"
      @click="emit('remove')"
    />
  </li>
</template>
